    path = rest
    rest = ''
  } else {
    path = rest.slice(0, pathEnd)
    rest = rest.slice(pathEnd)
  }

  let query
  if (rest.startsWith('?')) {
    rest = rest.slice(1)
    const end = rest.indexOf('#')
    if (end === -1) {
